export type PriceRow={date:string,close:number};
export function parseHistoryCSV(text:string):PriceRow[]{const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<3||lines.length>3001)throw new Error('헤더와 2~3000개의 일별 가격 행을 입력하세요.');const split=(s:string)=>s.split(',').map(x=>x.trim().replace(/^"|"$/g,''));const headers=split(lines.shift()!).map(x=>x.toLowerCase());const di=headers.findIndex(x=>['date','날짜','일자'].includes(x)),ci=headers.findIndex(x=>['close','종가'].includes(x));if(di<0||ci<0)throw new Error('CSV 헤더는 date,close 또는 날짜,종가를 사용하세요. 가격은 쉼표 없는 숫자로 입력하세요.');const rows:PriceRow[]=[];for(const line of lines){if(!line.trim())continue;const cols=split(line),date=cols[di]?.replace(/[.\/-]/g,''),close=Number(cols[ci]);if(!/^\d{8}$/.test(date)||!Number.isFinite(close)||close<=0)throw new Error('날짜 또는 종가가 올바르지 않은 행이 있습니다.');const iso=date.slice(0,4)+'-'+date.slice(4,6)+'-'+date.slice(6);if(!Number.isFinite(Date.parse(iso))||new Date(iso).toISOString().slice(0,10)!==iso||Date.parse(iso)>Date.now())throw new Error('유효한 과거 날짜만 입력하세요.');rows.push({date,close});}if(rows.length<2)throw new Error('최소 2개 종가가 필요합니다.');if(new Set(rows.map(x=>x.date)).size!==rows.length)throw new Error('중복 날짜가 있습니다. 하루당 한 행만 입력하세요.');return rows.sort((a,b)=>a.date.localeCompare(b.date));}
export function historyWindow(rows:PriceRow[],years:number){const start=new Date();start.setUTCFullYear(start.getUTCFullYear()-years);const cutoff=start.toISOString().slice(0,10).replaceAll('-','');return rows.filter(r=>r.date>=cutoff);}
