import {createDecipheriv} from 'node:crypto';
import {Buffer} from 'node:buffer';
import {koreanPrice,type AptTrade} from './apartment-data';
export function asilRequestInfo(html:string){const sido=html.match(/newver_6\.jsp\?sido=(\d{2})&/)?.[1];const seq=html.match(/&seq=(\d+)&m2=/)?.[1];const publicKey=html.match(/getKey\("([^"\n]{1,80})"\)/)?.[1];const types=[...html.matchAll(/search3\(\d+,\s*'(\d+)',\s*'(\d+)'\)/g)].map(m=>({area:m[1],py:m[2]}));if(!sido||!seq||!publicKey||!types.length)throw Error('아실 거래 조회 형식이 변경되어 내역을 읽지 못했습니다.');return {sido,seq,publicKey,types};}
// The public page supplies this presentation key to every guest browser.
// This decodes the same displayed fields; it is not an account credential.
export function parseAsilTrades(raw:string,keyText:string,url:string):AptTrade[]{const data=JSON.parse(raw);if(!Array.isArray(data))throw Error('아실 거래 응답 형식을 확인할 수 없습니다.');if(!data.length)return [];if(!Array.isArray(data[0]?.val))throw Error('아실 거래 목록을 확인할 수 없습니다.');const input=Buffer.from(keyText,'utf8');const len=input.length<=16?16:input.length<=24?24:32;const key=Buffer.alloc(len);input.copy(key,0,0,len);const decode=(value:unknown)=>{if(typeof value!=='string')throw Error('아실 가격 형식 오류');const cipher=createDecipheriv('aes-'+(len*8)+'-ecb',key,null);return Buffer.concat([cipher.update(Buffer.from(value,'base64')),cipher.final()]).toString('utf8');};const result:AptTrade[]=[];const occurrences=new Map<string,number>();for(const month of data[0].val){if(!/^\d{6}$/.test(month.yyyymm)||!Array.isArray(month.val))throw Error('아실 계약일 형식 오류');for(const day of month.val){if(!Array.isArray(day.val))throw Error('아실 거래일 형식 오류');for(const p of day.val){const rent=decode(p.rent);if(rent!=='')continue;const price=koreanPrice(decode(p.money));const building=decode(p.dong);const date=month.yyyymm.slice(0,4)+'-'+month.yyyymm.slice(4)+'-'+String(day.day).padStart(2,'0');if(!price||!Number.isFinite(Date.parse(date)))throw Error('아실 매매가격 또는 계약일 확인 실패');const fingerprint=[month.yyyymm,day.day,p.k,p.a,p.s,p.option,p.type,p.floor,price].join(':');const occurrence=(occurrences.get(fingerprint)||0)+1;occurrences.set(fingerprint,occurrence);result.push({id:fingerprint+':'+occurrence,date,price,area:Number(String(p.type).match(/\d+(?:\.\d+)?/)?.[0])||null,areaType:String(p.type||''),building:building&&building!=='-'?building+'동':'',floor:String(p.floor)+'층',cancelled:String(p.option)==='1',source:'아실',sourceUrl:url});}}}return result;}
