import {asilRequestInfo,parseAsilTrades} from './asil-trades';
import {cache,records} from './server';
import {parseApartmentSearch,parseApartment,parseApartmentListings,parseAsilPage,royalCandidates} from './apartment-data';
const hosts=new Set(['hogangnono.com','asil.kr','www.asil.kr']);
export async function estatePage(raw:string,guest?:{cookie?:string;referer?:string;onCookie?:(value:string)=>void}){let url=new URL(raw);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),16000);try{for(let i=0;i<4;i++){if(url.protocol!=='https:'||url.port||url.username||url.password||!hosts.has(url.hostname))throw Error('허용되지 않은 부동산 출처입니다.');const r=await fetch(url.href,{redirect:'manual',headers:{Accept:'text/html,application/json',...(url.hostname==='asil.kr'&&guest?.cookie?{Cookie:guest.cookie}:{}),...(url.hostname==='asil.kr'&&guest?.referer?{Referer:guest.referer}:{})},signal:controller.signal});if([301,302,303,307,308].includes(r.status)){const to=r.headers.get('location');await r.body?.cancel();if(!to)throw Error('원문 이동 주소를 확인할 수 없습니다.');url=new URL(to,url);continue;}if(url.hostname==='asil.kr'){const session=r.headers.get('set-cookie')?.match(/(?:^|,\s*)(JSESSIONID=[^;,\s]{1,400})/i)?.[1];if(session)guest?.onCookie?.(session);}
if(!r.ok){await r.body?.cancel();throw Error('원문 접근 제한 또는 응답 오류 ('+r.status+').');}const reader=r.body?.getReader();if(!reader)throw Error('원문 응답이 비어 있습니다.');const chunks:Uint8Array[]= [];let size=0;while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>3500000){await reader.cancel();throw Error('원문이 너무 큽니다.');}chunks.push(value);}const bytes=new Uint8Array(size);let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length;}if(!size)throw Error('원문 응답이 비어 있습니다.');const charset=/charset\s*=\s*["']?(euc-kr|ks_c_5601-1987)/i.test(r.headers.get('content-type')||'')?'euc-kr':'utf-8';return new TextDecoder(charset).decode(bytes);}throw Error('원문 이동 횟수를 초과했습니다.');}catch(e){if(controller.signal.aborted)throw Error('원문 응답 시간이 초과됐습니다. 다시 조회해 주세요.');throw e;}finally{clearTimeout(timer);}}
export async function apartmentSearch(input:any){const q=typeof input.query==='string'?input.query.trim():'';if(q.length<2||q.length>60)throw Error('아파트명 또는 지역과 아파트명을 2~60자로 입력하세요.');return {items:parseApartmentSearch(await estatePage('https://hogangnono.com/search?q='+encodeURIComponent(q)+'&ref=opensearch'))};}
export async function apartmentList(owner:string){return {items:(await records(owner)).filter(x=>x.kind.startsWith('apartment-')).map(x=>({id:x.apt.id,name:x.apt.name,address:x.apt.address,fetchedAt:x.fetchedAt}))};}
export async function apartmentRead(owner:string,id:string){if(!/^[a-zA-Z0-9]{1,20}$/.test(id))throw Error('단지 식별자를 확인해 주세요.');return (await records(owner,'apartment-'+id))[0]||null;}
const sameName=(a:string,b:string)=>a.replace(/[\s()]/g,'')===b.replace(/[\s()]/g,'');
async function asil(apt:any){const search=JSON.parse(await estatePage('https://asil.kr/json/getAptname_ver_3_4.jsp?os=pc&aptname='+encodeURIComponent(apt.name)));if(!Array.isArray(search))throw Error('아실 검색 결과 형식을 확인할 수 없습니다.');const candidates=search.filter(x=>sameName(x.name||'',apt.name)&&/^\d+$/.test(x.seq)&&String(x.type)==='1'&&String(x.desc).split(' / ')[0].trim().split(/\s+/).slice(1).every((word:string)=>apt.address.includes(word)));if(candidates.length!==1)throw Error('아실에서 이름·지역이 일치하는 단지를 하나로 확인하지 못했습니다. 원문에서 주소를 확인해 주세요.');const url='https://asil.kr/app/apt_info.jsp?apt='+candidates[0].seq+'&os=pc';let cookie='';const html=await estatePage(url,{onCookie:v=>{cookie=v;}});const page=parseAsilPage(html,url);let trades=page.trades;let note='공개 거래표에서 확인한 내역입니다.';let areaCoverage='';let available=trades.length>0;if(!trades.length){try{const info=asilRequestInfo(html);if(info.seq!==candidates[0].seq)throw Error('아실 단지 식별자가 일치하지 않습니다.');const types=info.types.slice(0,12);const all=await Promise.allSettled(types.map(async t=>{const query=new URLSearchParams({sido:info.sido,dealmode:'123',building:'apt',seq:info.seq,m2:t.area,py:t.py,py_type:'',isPyQuery:'true',year:'9999',start:'0',count:'20',u:'0',order:''});return parseAsilTrades(await estatePage('https://asil.kr/app/data/apt_price_m2_mjw_newver_6.jsp?'+query,{cookie,referer:url}),info.publicKey,url);}));const success=all.filter(x=>x.status==='fulfilled');if(!success.length)throw Error('아실 거래 응답을 읽지 못했습니다.');available=true;trades=[...new Map(success.flatMap(x=>x.status==='fulfilled'?x.value:[]).map(x=>[x.id,x])).values()].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,100);areaCoverage=`${info.types.length}개 평형 중 ${success.length}개 조회 · 평형별 최근 매매·임대 20건에서 매매만 추출`;note=success.length<info.types.length?'일부 평형만 조회됐습니다.':'조회한 평형의 최근 공개 매매입니다.';}catch{note='아실 실거래 응답을 읽지 못했습니다. 아래 호갱노노 실거래를 대체 표시합니다.';}}return {...page,trades,url,message:note,areaCoverage,available};}
export async function apartmentRefresh(owner:string,input:any){const id=String(input.id||'');const old=await apartmentRead(owner,id);const apt=parseApartment(await estatePage('https://hogangnono.com/apt/'+id),id);const now=new Date().toISOString();const results=await Promise.allSettled([estatePage(apt.sourceUrl+'/item-catalog').then(h=>parseApartmentListings(h,id)),asil(apt)]);const [listing,asilResult]=results;const data:any={apt,fetchedAt:now,listings:listing.status==='fulfilled'?{...listing.value,fetchedAt:now}:old?.listings||null,listingError:listing.status==='rejected'?(listing.reason as Error).message:null,asil:asilResult.status==='fulfilled'&&(asilResult.value.available||!old?.asil)?{...asilResult.value,fetchedAt:now}:old?.asil||null,asilError:asilResult.status==='rejected'?(asilResult.reason as Error).message:!asilResult.value.available?asilResult.value.message:null};data.royal=royalCandidates(apt.buildings,data.listings?.items||[]);await cache(owner,'apartment-'+id,data);return data;}
