import {load} from 'cheerio/slim';
export type AptChoice={id:string;name:string;address:string;households:number};
export type AptListing={id:string;price:number;area:number;publicArea:number|null;building:string;floor:string;description:string;sourceUrl:string;type:string};
export type AptTrade={id:string;date:string;price:number;area:number|null;areaType:string;building:string;floor:string;cancelled:boolean;source:string;sourceUrl:string};
const clean=(v:unknown)=>typeof v==='string'?v.replace(/\s+/g,' ').trim():'';
const num=(v:unknown)=>{const n=Number(v);return v!==null&&v!==''&&Number.isFinite(n)&&n>0?n:null;};
export function hgnData(html:string){const $=load(html);try{return JSON.parse($('#__HGNN_DATA__').text());}catch{throw Error('호갱노노 공개 페이지를 읽지 못했습니다. 이전 조회값을 유지합니다.');}}
export function parseApartmentSearch(html:string):AptChoice[]{const list=hgnData(html)?.altState?.SearchStore?.searchResults?.apt?.list;if(!Array.isArray(list))throw Error('단지 검색 결과를 읽지 못했습니다.');return list.filter(x=>/^[a-zA-Z0-9]{1,20}$/.test(x.id)&&x.type===0&&clean(x.name)).slice(0,20).map(x=>({id:x.id,name:clean(x.name),address:clean(x.address),households:num(x.household)||0}));}
export function parseApartment(html:string,id:string){const d=hgnData(html)?.altState?.AptStore?.detail;if(d?.id!==id||!clean(d?.name))throw Error('선택한 단지와 조회된 단지가 일치하지 않습니다.');const url='https://hogangnono.com/apt/'+id;const areas=(d.area||[]).filter((a:any)=>num(a.private_area)).map((a:any)=>({type:clean(a.area_type),area:Number(a.private_area)}));const trades:AptTrade[]=(d.molitTradeReal||[]).filter((t:any)=>t.category===1&&num(t.price)&&Number.isFinite(Date.parse(t.date))).map((t:any)=>{const matched=areas.filter((a:any)=>clean(t.areaType).split('/').includes(a.type));const values=[...new Set(matched.map((a:any)=>a.area))];return {id:String(t.id),date:new Date(Date.parse(t.date)+9*3600000).toISOString().slice(0,10),price:Number(t.price),area:values.length===1?values[0]:null,areaType:clean(t.areaType),building:clean(t.dong),floor:t.floor==null?'미공개':String(t.floor),cancelled:t.isCancelled===true,source:'호갱노노',sourceUrl:url};});return {id,name:clean(d.name),address:clean(d.address),households:num(d.total_household),maxFloor:num(d.baseinfo?.floor_max),buildings:(d.dongList||[]).filter((x:any)=>clean(x.name)).map((x:any)=>({name:clean(x.name),maxFloor:num(x.highest_floor),popular:x.isPopular===true})),areas,trades,sourceUrl:url,sourceUpdatedAt:typeof d.molitUpdatedDate==='string'?d.molitUpdatedDate:null};}
export function parseApartmentListings(html:string,id:string){const d=hgnData(html);const q=d?.queryState?.queries?.find((q:any)=>q.queryKey?.some((k:any)=>k.entity==='getAptItemCatalogsInfinite'&&k.params?.aptHash===id));const pages=q?.state?.data?.pages;if(!Array.isArray(pages)||!Array.isArray(pages[0]?.itemCatalogSummaries))throw Error('매물 목록을 읽지 못했습니다. 이전 매물을 유지합니다.');const items:AptListing[]=pages.flatMap((p:any)=>p.itemCatalogSummaries).filter((x:any)=>x.aptHash===id&&x.tradeType===0&&num(x.deposit)&&num(x.privateArea)&&!x.isPriceRange).map((x:any)=>({id:String(x.areaHoId)+':'+String(x.itemIds?.[0]?.itemId),price:Number(x.deposit),area:Number(x.privateArea),publicArea:num(x.publicArea),building:clean(x.aptDongName),floor:x.floor==null?'미공개':String(x.floor),description:clean(x.itemTitle).slice(0,250),sourceUrl:'https://hogangnono.com/apt/'+id+'/item-catalog',type:clean(x.danjiRoomType)}));return {items:[...new Map(items.map(x=>[x.id,x])).values()],totalSale:Number(pages[0].itemCatalogCountPerTradeType?.trade)||0,loadedAllTypes:pages.reduce((s:number,p:any)=>s+p.itemCatalogSummaries.length,0),totalAllTypes:Number(pages[0].itemCatalogTotalCount)||0};}
export function parseAsilPage(html:string,url:string){const $=load(html);const name=clean($('h1,h2').first().text());const text=clean($('body').text());const address=text.match(/주소\s*:\s*(.+?)\s*사용승인/)?.[1]||'';const rows:AptTrade[]=[];let month='';$('#tableList tbody tr').each((_,el)=>{const row=$(el);const m=clean(row.find('.mm').text());if(m)month=m;const day=clean(row.find('.dd').text());const priceText=clean(row.find('.price .eb').text());if(!/매매/.test(row.find('.price').text()))return;const match=month.match(/^(\d{2}|\d{4})\.(\d{2})$/);if(!match||!/^\d{1,2}$/.test(day))return;const date=(match[1].length===2?'20':'')+match[1]+'-'+match[2]+'-'+day.padStart(2,'0');const price=koreanPrice(priceText);if(!price||!Number.isFinite(Date.parse(date)))return;rows.push({id:date+':'+rows.length,date,price,area:num(clean(row.find('.type').text())),areaType:clean(row.find('.type').text()),building:clean(row.find('.aptdong').text()),floor:clean(row.find('.aptfloor').text()),cancelled:/취소/.test(row.text()),source:'아실',sourceUrl:url});});const naverId=html.match(/groundPlan\.nhn\?rletTypeCd=A01&amp;rletNo=(\d+)/)?.[1]||html.match(/groundPlan\.nhn\?rletTypeCd=A01&rletNo=(\d+)/)?.[1];return {name,address,trades:rows,naverUrl:naverId?'https://fin.land.naver.com/complexes/'+naverId:null};}
export function koreanPrice(value:string){const s=value.replace(/[ ,]/g,'');if(/^\d+(?:\.\d+)?억(?:\d+(?:만)?)?$/.test(s)){const [a,b]=s.split('억');return Number(a)*10000+Number((b||'0').replace('만',''));}if(/^\d+(?:만|만원)?$/.test(s))return Number(s.replace(/만원?|원/g,''));return null;}
export function royalCandidates(buildings:any[],items:AptListing[]){return buildings.map(b=>{const matching=items.filter(x=>x.building.replace(/동$/,'')===b.name);const claims=matching.filter(x=>/로[얄열]동|조망|[강산숲]뷰|채광|일조/.test(x.description));const floors=matching.filter(x=>/로[얄열]층/.test(x.description));return {...b,claims:claims.map(x=>({id:x.id,text:x.description,floor:x.floor,url:x.sourceUrl})),floors:floors.map(x=>({floor:x.floor,text:x.description,url:x.sourceUrl})),evidenceCount:claims.length+(b.popular?1:0)};}).filter(b=>b.evidenceCount||b.floors.length).sort((a,b)=>b.evidenceCount-a.evidenceCount).slice(0,8);}
