import {credentials,saveCredentials,setting,records,cache} from './server';
import {TEAM_MODEL,teamModel} from './ai-team';
import {openAI,solRequest,resultSchema,aiFailureMessage} from './sol';
export async function providerConfig(owner:string){const c=await credentials(owner),prefs=(await records(owner,'ai-preference'))[0];return {providers:{openai:!!(c.openaiKey||setting('OPENAI_API_KEY')),anthropic:!!(c.anthropicKey||setting('ANTHROPIC_API_KEY'))},openaiKeySource:c.openaiKey?'personal':setting('OPENAI_API_KEY')?'server':'none',selectedModel:teamModel(prefs?.model)?.id||TEAM_MODEL};}
export async function saveModelPreference(owner:string,b:any){if(!teamModel(b.model))throw new Error('지원하는 모델을 선택하세요.');await cache(owner,'ai-preference',{model:b.model});return {ok:true};}
export async function saveClaudeKey(owner:string,b:any){const value=typeof b.key==='string'?b.key.trim():'';if(value.length<20||value.length>512||!/^[A-Za-z0-9_-]+$/.test(value))throw new Error('Claude API 키 형식을 확인하세요.');const c=await credentials(owner);c.anthropicKey=value;await saveCredentials(owner,c);return {ok:true};}
export async function saveOpenAIKey(owner:string,b:any){const value=typeof b.key==='string'?b.key.trim():'';if(value.length<20||value.length>512||!/^sk-[A-Za-z0-9_-]+$/.test(value))throw new Error('OpenAI API 키 형식을 확인하세요.');const c=await credentials(owner);c.openaiKey=value;await saveCredentials(owner,c);return {ok:true};}
export function claudeRequest(job:any,index:number){const base=solRequest(job,index);return {model:job.model,max_tokens:4200,system:base.instructions+' 이 업무에서는 웹 검색 도구를 사용할 수 없다. 입력 자료와 저장된 뉴스만 분석하고 외부 정보를 새로 조회했다고 주장하지 않는다.',messages:[{role:'user',content:base.input}],output_config:{format:{type:'json_schema',schema:resultSchema}}};}
export async function submitTeamResponse(owner:string,job:any,index:number){if(job.provider!=='anthropic')return openAI(owner,'responses',solRequest(job,index));const c=await credentials(owner),key=c.anthropicKey||setting('ANTHROPIC_API_KEY');if(!key)throw new Error('Claude API 키를 먼저 저장하세요.');let response:Response;try{response=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'x-api-key':key,'anthropic-version':'2023-06-01','Content-Type':'application/json'},body:JSON.stringify(claudeRequest(job,index)),redirect:'manual',signal:AbortSignal.timeout(90000)});}catch{throw new Error('Claude 응답을 확인하지 못했습니다. 접수 여부가 불확실하므로 자동 재요청하지 않습니다. 다시 실행하면 추가 사용량이 발생할 수 있습니다.');}
 if(!response.ok)throw new Error(response.status===401?'Claude API 키 인증에 실패했습니다. 키를 확인해 주세요.':response.status===402?'Claude API 크레딧을 확인하세요.':response.status===403?'Claude 모델 사용 권한을 확인하세요.':response.status===404?'선택한 Claude 모델을 사용할 수 없습니다. 다른 모델로 새 업무를 등록하세요.':response.status===429?'Claude 요청 한도에 도달했습니다. 잠시 후 다시 실행하세요.':response.status===400?'Claude 요청을 처리하지 못했습니다. 모델 이용 가능 여부와 API 크레딧을 확인하세요.':`Claude 요청을 처리하지 못했습니다 (${response.status}).`);
 let data:any;try{data=await response.json();}catch{throw new Error('Claude 응답 형식을 확인하지 못했습니다.');}
 if(data.stop_reason==='max_tokens')throw new Error('Claude 응답 길이 제한에 도달했습니다. 지시를 간결하게 작성해 주세요.');if(data.stop_reason==='refusal')throw new Error('Claude가 이 요청을 처리할 수 없다고 응답했습니다.');if(data.stop_reason!=='end_turn'||!data.id)throw new Error('Claude 응답이 정상적으로 완료되지 않았습니다.');
 return {id:data.id,model:data.model,status:'completed',output:[{type:'message',content:(data.content||[]).filter((b:any)=>b.type==='text').map((b:any)=>({type:'output_text',text:b.text}))}],usage:{input_tokens:data.usage?.input_tokens||0,output_tokens:data.usage?.output_tokens||0,total_tokens:(data.usage?.input_tokens||0)+(data.usage?.output_tokens||0)}};
}
export async function pollTeamResponse(owner:string,job:any,responseId:string){if(job.provider==='anthropic')throw new Error('Claude의 완료되지 않은 요청은 다시 조회할 수 없습니다. 해당 단계를 다시 실행하세요.');return openAI(owner,'responses/'+encodeURIComponent(responseId));}
export async function cancelTeamResponse(owner:string,job:any,responseId:string){if(job.provider!=='anthropic')await openAI(owner,'responses/'+encodeURIComponent(responseId)+'/cancel',{});}

export async function checkOpenAI(owner:string){const checkedAt=new Date().toISOString();try{const r:any=await openAI(owner,'responses',{model:TEAM_MODEL,input:'Reply only with OK.',max_output_tokens:64,reasoning:{effort:'low'},store:false});if(r.status==='failed')return {ok:false,checkedAt,model:TEAM_MODEL,code:r.error?.code||'generation_failed',message:aiFailureMessage(r.error?.code)};if(r.status!=='completed')return {ok:false,checkedAt,model:TEAM_MODEL,code:'incomplete',message:'요청은 접수됐지만 테스트 응답이 완료되지 않았습니다.'};return {ok:true,checkedAt,model:r.model||TEAM_MODEL,message:'현재 적용된 GPT API 키로 응답 생성에 성공했습니다.'};}catch(e){return {ok:false,checkedAt,model:TEAM_MODEL,code:(e as any).code||'connection_error',message:(e as Error).message};}}
