import {records,db,cache} from './server';
import {parseKospiMembers,parseChartFeed,technicalRank,validRankCode,rankCutoff,MEMBER_SOURCE} from './kospi-data';
const JOB='kospi-ranking-job',DONE='kospi-ranking-complete';
export async function rankPage(raw:string){let url=new URL(raw);const signal=AbortSignal.timeout(12000);for(let n=0;n<3;n++){if(url.protocol!=='https:'||url.port||url.username||url.password||!['markets.hankyung.com','fchart.stock.naver.com'].includes(url.hostname))throw Error('허용되지 않은 랭킹 출처입니다.');const r=await fetch(url.href,{signal,redirect:'manual',headers:{Accept:'text/html,application/xml,text/xml'},cache:'no-store'});if([301,302,303,307,308].includes(r.status)){const next=r.headers.get('location');await r.body?.cancel();if(!next)throw Error('출처 이동 주소가 없습니다.');url=new URL(next,url);continue;}if(!r.ok){await r.body?.cancel();throw Error('공개 시세 응답 오류 ('+r.status+')');}const reader=r.body?.getReader();if(!reader)throw Error('출처 응답이 비어 있습니다.');const chunks:Uint8Array[]=[];let size=0;while(true){const x=await reader.read();if(x.done)break;size+=x.value.length;if(size>2500000){await reader.cancel();throw Error('출처 크기 제한 초과');}chunks.push(x.value);}const bytes=new Uint8Array(size);let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length;}return new TextDecoder(/euc-kr/i.test(r.headers.get('content-type')||'')?'euc-kr':'utf-8').decode(bytes);}throw Error('출처 이동 횟수 초과');}
export async function rankBars(code:string,count=80){if(!validRankCode(code))throw Error('종목코드 오류');return parseChartFeed(await rankPage(`https://fchart.stock.naver.com/sise.nhn?symbol=${code}&timeframe=day&count=${count}&requestType=0`),code);}
async function job(owner:string){return (await records(owner,JOB))[0]||null;}
async function write(owner:string,version:number,data:any){const result=await db().prepare('UPDATE records SET data=?,version=version+1,updated=? WHERE id=? AND owner=? AND kind=? AND version=?').bind(JSON.stringify(data),new Date().toISOString(),owner+':'+JOB,owner,JOB,version).run();if(!result.meta.changes)throw Error('다른 화면에서 조회가 진행 중입니다. 이어서 조회해 주세요.');return {...data,version:version+1};}
function view(j:any){if(!j)return null;return {runId:j.runId,status:j.status,members:j.members||[],items:[...(j.items||[])].sort((a:any,b:any)=>(b.score??-1)-(a.score??-1)||a.code.localeCompare(b.code)),done:j.next||0,total:j.members?.length||0,startedAt:j.startedAt,finishedAt:j.finishedAt,anchor:j.anchor,error:j.error||null,sourceUrl:MEMBER_SOURCE,leaseUntil:j.leaseUntil||0};}
export async function rankingState(owner:string){const active=await job(owner);return {job:view(active),previous:view((await records(owner,DONE))[0])};}
export async function rankingStart(owner:string){let old=await job(owner);if(old&&old.leaseUntil>Date.now())return {job:view(old),waiting:true};if(old?.status==='running'&&Date.now()-Date.parse(old.startedAt)<86400000)return {job:view(old)};if(!old){await db().prepare('INSERT INTO records(id,owner,kind,data,updated) VALUES(?,?,?,?,?) ON CONFLICT(id) DO NOTHING').bind(owner+':'+JOB,owner,JOB,'{}',new Date().toISOString()).run();old=await job(owner);}const now=new Date();const loading=await write(owner,old.version,{runId:crypto.randomUUID(),status:'loading',members:[],items:[],next:0,startedAt:now.toISOString(),leaseUntil:Date.now()+60000});try{const members=parseKospiMembers(await rankPage(MEMBER_SOURCE));const bars=await rankBars(members[0].code);const cut=rankCutoff(now);const anchor=bars.filter(r=>r.date<cut.day||cut.includeToday&&r.date===cut.day).at(-1)?.date;if(!anchor)throw Error('기준 거래일을 확인하지 못했습니다.');const next=await write(owner,loading.version,{...loading,status:'running',members,anchor,leaseUntil:0});return {job:view(next)};}catch(e){await write(owner,loading.version,{...loading,status:'failed',error:e instanceof Error?e.message:'구성 종목 조회 실패',leaseUntil:0});throw e;}}
export async function rankingAdvance(owner:string,input:any){const current=await job(owner);if(!current||current.runId!==input.runId)throw Error('조회 작업이 바뀌었습니다. 화면을 다시 열어 주세요.');if(current.status==='complete')return {job:view(current)};if(current.status!=='running')throw Error('새로 랭킹 조회를 시작해 주세요.');if(current.leaseUntil>Date.now())return {job:view(current),waiting:true};const locked=await write(owner,current.version,{...current,leaseUntil:Date.now()+60000});const list=locked.members.slice(locked.next,locked.next+6),items=[];for(let i=0;i<list.length;i+=3){const result=await Promise.all(list.slice(i,i+3).map(async(m:any)=>{try{return {...m,...technicalRank(await rankBars(m.code),new Date(locked.startedAt),locked.anchor),fetchedAt:new Date().toISOString()};}catch(e){return {...m,score:null,label:'조회 실패',reason:e instanceof Error?e.message:'시세 조회 실패',plan:null,factors:[],date:null};}}));items.push(...result);}const next=locked.next+list.length;const data={...locked,next,items:[...locked.items,...items],leaseUntil:0,status:next>=locked.members.length?'complete':'running',finishedAt:next>=locked.members.length?new Date().toISOString():null};const saved=await write(owner,locked.version,data);if(saved.status==='complete')await cache(owner,DONE,data);return {job:view(saved)};}
export async function rankingChart(owner:string,input:any){const code=input.code;if(!validRankCode(code))throw Error('종목코드 오류');const j=await job(owner),previous=(await records(owner,DONE))[0];if(![...(j?.members||[]),...(previous?.members||[])].some(m=>m.code===code))throw Error('코스피200 랭킹을 먼저 조회해 주세요.');const kind='rank-chart-'+code;const old=(await records(owner,kind))[0];if(old&&!input.restart&&Date.now()-Date.parse(old.fetchedAt)<12*3600000)return old;const rows=await rankBars(code,1500);const cutoff=new Date();cutoff.setUTCFullYear(cutoff.getUTCFullYear()-5);const from=cutoff.toISOString().slice(0,10).replaceAll('-','');const visible=rows.filter(r=>r.date>=from);if(!visible.length)throw Error('선택 기간의 차트 데이터가 없습니다.');const result={code,years:5,rows:visible,complete:true,loaded:visible.length,earliest:visible[0].date,latest:visible.at(-1)!.date,requestedFrom:from,fullPeriod:rows[0].date<=from,fetchedAt:new Date().toISOString(),source:'네이버 증권 공개 차트 시세',sourceUrl:`https://m.stock.naver.com/domestic/stock/${code}/total`};await cache(owner,kind,result);return result;}
