import {load} from 'cheerio/slim';
import {records,cache} from './server';
export type MarketBar={date:string,open:number|null,high:number|null,low:number|null,close:number,volume:number};
export function parseDailyTable(html:string,code:string){const $=load(html),rows:MarketBar[]=[];const number=(s:string)=>Number(s.replaceAll(',','').trim());$('table.type2 tr').each((_,el)=>{const cells=$(el).find('td');if(cells.length!==7)return;const date=cells.eq(0).text().trim().replaceAll('.','');if(!/^\d{8}$/.test(date))return;const close=number(cells.eq(1).text()),open=number(cells.eq(3).text()),high=number(cells.eq(4).text()),low=number(cells.eq(5).text()),volume=number(cells.eq(6).text());if(!(close>0)||!Number.isFinite(close)||!Number.isFinite(volume)||volume<0)throw new Error('일별 시세 값이 올바르지 않습니다.');const ohlc=open>0&&high>=Math.max(open,close)&&low>0&&low<=Math.min(open,close);rows.push({date,close,volume,open:ohlc?open:null,high:ohlc?high:null,low:ohlc?low:null});});if(!rows.length)throw new Error('공개 일별 시세표를 읽지 못했습니다. 잠시 후 이어서 가져오세요.');let lastPage=1;$('.Nnavi a[href]').each((_,el)=>{const u=new URL($(el).attr('href')!,'https://finance.naver.com');if(u.searchParams.get('code')===code){const p=Number(u.searchParams.get('page'));if(Number.isInteger(p)&&p>lastPage)lastPage=p;}});return {rows:rows.sort((a,b)=>a.date.localeCompare(b.date)),lastPage};}
async function dailyPage(code:string,p:number){const url=`https://finance.naver.com/item/sise_day.naver?code=${code}&page=${p}`;const r=await fetch(url,{headers:{'User-Agent':'Mozilla/5.0',Referer:'https://finance.naver.com/',Accept:'text/html'},redirect:'manual',cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)throw new Error(`네이버 일별 시세 응답 오류 (${r.status}). 잠시 후 이어서 가져오세요.`);const html=await r.text();if(html.length>250000)throw new Error('일별 시세 응답 크기를 확인하세요.');return parseDailyTable(html,code);}
export function mergeBars(rows:MarketBar[],more:MarketBar[]){return [...new Map([...rows,...more].map(r=>[r.date,r])).values()].sort((a,b)=>a.date.localeCompare(b.date));}
export async function refreshMarketHistory(owner:string,b:any){const code=b.code,years=Number(b.years);if(!/^\d{6}$/.test(code)||![1,5].includes(years))throw new Error('종목코드와 조회 기간을 확인하세요.');if(!(await records(owner,'holding')).some(h=>h.code===code))throw new Error('등록된 보유 종목만 조회할 수 있습니다.');
 const kind=`market-history-${code}-${years}`,jobKind=`chart-job-${code}-${years}`;const stored=(await records(owner,kind))[0];
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date());const cutoffDate=new Date(today+'T12:00:00Z');cutoffDate.setUTCFullYear(cutoffDate.getUTCFullYear()-years);const cutoff=cutoffDate.toISOString().slice(0,10).replaceAll('-','');
 let job=(await records(owner,jobKind))[0];const age=stored?Date.now()-Date.parse(stored.fetchedAt):Infinity;if(!b.restart&&!b.continue&&stored&&age>=0&&age<12*3600000&&(!job||job.complete))return {...stored,complete:true};if(!b.restart&&job?.complete&&b.jobId===job.jobId&&stored?.jobId===job.jobId)return {...stored,complete:true};if(b.restart||!job||job.anchor!==today||job.complete){job={code,years,anchor:today,cutoff,rows:[],nextPage:1,lastPage:160,jobId:crypto.randomUUID()};}
 if(b.jobId&&b.jobId!==job.jobId)throw new Error('다른 화면에서 조회가 시작되었습니다. 다시 가져오세요.');
 if(job.nextPage===1){const first=await dailyPage(code,1);job={...job,rows:first.rows,lastPage:first.lastPage,nextPage:2};}
 else {const end=Math.min(job.nextPage+7,job.lastPage,160),pages=Array.from({length:end-job.nextPage+1},(_,i)=>job.nextPage+i);let added:MarketBar[]=[];
  for(let i=0;i<pages.length;i+=4){const results=await Promise.all(pages.slice(i,i+4).map(p=>dailyPage(code,p)));added.push(...results.flatMap(r=>r.rows));}
  const earliest=job.rows[0]?.date;if(added.length&&earliest&&added.every(r=>r.date>=earliest))throw new Error('이전 날짜 시세를 확인하지 못했습니다. 다시 가져오세요.');job={...job,rows:mergeBars(job.rows,added),nextPage:end+1};
 }
 const reachedDate=job.rows[0]?.date<=cutoff,exhausted=job.nextPage>job.lastPage;const complete=reachedDate||exhausted;
 if(!complete&&job.nextPage>160)throw new Error('조회 가능한 페이지 범위를 넘었습니다. 원문을 확인하세요.');
 const latestJob=(await records(owner,jobKind))[0];if(latestJob&&latestJob.jobId!==job.jobId&&!b.restart&&b.jobId)throw new Error('다른 조회가 진행 중입니다. 다시 시도해 주세요.');
 if(latestJob?.jobId===job.jobId&&latestJob.nextPage>job.nextPage)throw new Error('다른 화면에서 더 많은 시세를 가져왔습니다. 이어서 가져오세요.');
 await cache(owner,jobKind,{...job,complete,updatedAt:new Date().toISOString()});
 const visible=job.rows.filter((r:MarketBar)=>r.date>=cutoff);const result={code,years,rows:visible,complete,jobId:job.jobId,loaded:visible.length,earliest:visible[0]?.date||null,latest:visible.at(-1)?.date||null,requestedFrom:cutoff,fullPeriod:reachedDate,fetchedAt:new Date().toISOString(),source:'네이버증권 공개 일별 시세표',sourceUrl:`https://finance.naver.com/item/sise_day.naver?code=${code}`};
 if(complete)await cache(owner,kind,result);return result;
}
