import {providerConfig,submitTeamResponse,pollTeamResponse,cancelTeamResponse} from './ai-provider';
import {db,records,setting} from './server';
import {AI_TEAM,TEAM_MODEL,teamModel} from './ai-team';
import {responseResult,citedSources,aiFailureMessage} from './sol';
const now=()=>new Date().toISOString();
function publicJob(row:any){const {leaseToken,leaseUntil,context,...job}=row;return {...job,contextInfo:context?{asOf:context.asOf,holdings:context.holdings.length,news:context.news.length,sources:context.sources}:undefined,steps:job.steps.map((s:any)=>{const {responseId,...step}=s;return step;}),archives:(job.archives||[]).map((a:any)=>({...a,steps:a.steps.map((s:any)=>{const {responseId,...step}=s;return step;})}))};}
async function getJob(owner:string,id:string){if(typeof id!=='string'||!/^ai-[a-f0-9-]{36}$/.test(id))throw new Error('업무 번호를 확인하세요.');const row:any=await db().prepare("SELECT * FROM records WHERE id=? AND owner=? AND kind='ai-job'").bind(id,owner).first();if(!row)throw new Error('업무를 찾을 수 없습니다.');return {...JSON.parse(row.data),id:row.id,version:row.version};}
async function persist(owner:string,job:any){const {id,version,...data}=job;const result=await db().prepare("UPDATE records SET data=?,version=version+1,updated=? WHERE id=? AND owner=? AND kind='ai-job' AND version=? AND (?<>'running' OR NOT EXISTS (SELECT 1 FROM records other WHERE other.owner=? AND other.kind='ai-job' AND other.id<>? AND json_extract(other.data,'$.status')='running'))").bind(JSON.stringify(data),now(),id,owner,version,data.status,owner,id).run();if(!result.meta.changes)throw new Error('다른 화면에서 업무가 변경되었습니다. 최신 상태를 다시 확인하세요.');job.version++;return job;}
export async function teamList(owner:string){const rows=await db().prepare("SELECT id,data,version FROM records WHERE owner=? AND kind='ai-job' ORDER BY updated DESC LIMIT 30").bind(owner).all();const config=await providerConfig(owner);return {...config,configured:config.providers.openai||config.providers.anthropic,model:TEAM_MODEL,jobs:rows.results.map((row:any)=>publicJob({...JSON.parse(row.data),id:row.id,version:row.version}))};}
export async function createTeamJob(owner:string,b:any){const selected=teamModel(b.model===undefined?TEAM_MODEL:b.model);if(!selected)throw new Error('지원하는 모델을 선택하세요.');const config=await providerConfig(owner);if(!config.providers[selected.provider])throw new Error(selected.provider==='anthropic'?'Claude API 키를 먼저 저장하세요.':'OpenAI 연결 설정이 필요합니다.');const instruction=typeof b.instruction==='string'?b.instruction.trim():'',reference=typeof b.reference==='string'?b.reference.trim():'';if(instruction.length<5||instruction.length>3000||reference.length>12000)throw new Error('업무 지시는 5~3,000자, 참고 내용은 12,000자 이내로 입력하세요.');const id='ai-'+b.requestId;if(!/^ai-[a-f0-9-]{36}$/.test(id))throw new Error('업무 요청 번호를 확인하세요.');
 const existing:any=await db().prepare("SELECT data,id,version FROM records WHERE owner=? AND id=? AND kind='ai-job'").bind(owner,id).first();if(existing){const saved=JSON.parse(existing.data);if((saved.model||TEAM_MODEL)!==selected.id||saved.instruction!==instruction||saved.reference!==reference||saved.includeOffice!==(b.includeOffice===true))throw new Error('같은 요청 번호의 내용이 변경되었습니다. 새 지시를 등록하세요.');return publicJob({...saved,id,version:existing.version});}
 const saved=b.includeOffice===true?await records(owner):[];const quotes=saved.find(r=>r.kind==='quotes')?.items||{};
 const holdings=saved.filter(r=>r.kind==='holding').slice(0,40).map(h=>{const q=quotes[h.code],valuation=q?.price>0?q.price*h.quantity:null;return {name:h.name,code:h.code,quantity:h.quantity,totalCost:h.cost,averageCost:h.cost/h.quantity,price:q?.price??null,valuation,profit:valuation===null?null:valuation-h.cost,returnPct:valuation===null?null:100*(valuation-h.cost)/h.cost,priceFetchedAt:q?.fetchedAt??null,marketAt:q?.marketAt??null,lastFiveSessions:(q?.history||[]).slice(-5),sourceUrl:q?.sourceUrl??null};});
 const news=[...new Map(saved.filter(r=>r.kind==='news'||r.kind.startsWith('news-')).flatMap(r=>(r.items||[]).map((n:any)=>({title:n.title,url:n.url,summary:n.summaryPoints?.join(' ')||n.summary||'',publishedAt:n.publishedAt,fetchedAt:r.fetchedAt}))).map((n:any)=>[n.url,n])).values()].slice(0,20);
 const sources=[...holdings.filter(h=>h.sourceUrl).map(h=>({title:h.name+' 시세',url:h.sourceUrl})),...news.map(n=>({title:n.title,url:n.url}))].map((s,i)=>({...s,id:'S'+(i+1)}));
 const job={instruction,reference,context:{asOf:now(),holdings,news,sources},status:'running',model:selected.id,provider:selected.provider,createdAt:now(),includeOffice:b.includeOffice===true,steps:AI_TEAM.map(a=>({role:a.id,status:'queued',attempts:0})),revision:0,archives:[],decisions:[],leaseUntil:0};
 const result=await db().prepare("INSERT INTO records(id,owner,kind,data,updated) SELECT ?,?,'ai-job',?,? WHERE NOT EXISTS (SELECT 1 FROM records WHERE owner=? AND kind='ai-job' AND json_extract(data,'$.status')='running')").bind(id,owner,JSON.stringify(job),now(),owner).run();if(!result.meta.changes)throw new Error('진행 중인 팀 업무를 완료하거나 중단한 뒤 새 업무를 등록하세요.');return publicJob({...job,id,version:1});}
export async function advanceTeamJob(owner:string,id:string){let job=await getJob(owner,id);if(job.status!=='running'||job.leaseUntil>Date.now())return publicJob(job);const index=job.steps.findIndex((s:any)=>s.status!=='complete');if(index<0)return publicJob(job);
 const token=crypto.randomUUID();job.leaseToken=token;job.leaseUntil=Date.now()+(job.provider==='anthropic'?120000:45000);try{await persist(owner,job);}catch{return publicJob(await getJob(owner,id));}
 const step=job.steps[index];try{
  if(step.status==='starting'&&!step.responseId)throw new Error('이전 AI 요청의 접수 여부가 불확실합니다. 자동으로 중복 요청하지 않습니다. 다시 실행하면 추가 사용량이 발생할 수 있습니다.');
  let response:any;
  if(step.responseId){try{response=await pollTeamResponse(owner,job,step.responseId);}catch(e){job.lastPollError=(e as Error).message;step.pollFailures=(step.pollFailures||0)+1;if(step.pollFailures>=3){step.retryPoll=true;throw e;}job.leaseUntil=0;await persist(owner,job);return publicJob(job);}}
  else{step.status='starting';step.startedAt=now();step.attempts++;await persist(owner,job);response=await submitTeamResponse(owner,job,index);if(!response.id||typeof response.id!=='string')throw new Error('AI 요청 번호를 받지 못했습니다.');step.responseId=response.id;step.status='running';if(job.provider!=='anthropic')await persist(owner,job);}
  job.lastPollError='';step.pollFailures=0;step.retryPoll=false;
  if(response.status==='completed'){step.result=responseResult(response);step.model=response.model||job.model||TEAM_MODEL;step.sources=citedSources(response);step.usage=response.usage?{input:response.usage.input_tokens||0,output:response.usage.output_tokens||0,total:response.usage.total_tokens||0}:null;step.status='complete';step.completedAt=now();if(index===AI_TEAM.length-1)job.status='awaiting_decision';}
  else if(!['queued','in_progress'].includes(response.status))throw new Error(response.status==='incomplete'?'응답 길이 제한으로 분석을 마치지 못했습니다. 지시를 간결하게 수정해 주세요.':aiFailureMessage(response.error?.code));
 }catch(e){step.status='error';step.error=(e as Error).message;job.status='error';}
 job.leaseUntil=0;try{await persist(owner,job);}catch{return publicJob(await getJob(owner,id));}return publicJob(job);}
export async function retryTeamJob(owner:string,b:any){const job=await getJob(owner,b.id);if(job.status!=='error'||job.version!==b.version)throw new Error('최신 업무 상태에서 다시 실행하세요.');const step=job.steps.find((s:any)=>s.status==='error');if(!step||(step.attempts>=3&&!step.retryPoll))throw new Error('이 단계는 최대 3회 실행할 수 있습니다. 지시를 수정해 새 업무를 등록하세요.');const active=await db().prepare("SELECT id FROM records WHERE owner=? AND kind='ai-job' AND json_extract(data,'$.status')='running' AND id<>?").bind(owner,b.id).first();if(active)throw new Error('다른 진행 중인 업무를 먼저 완료하세요.');if(step.retryPoll&&step.responseId){step.status='running';step.pollFailures=0;}else{step.status='queued';delete step.responseId;}delete step.error;job.lastPollError='';job.status='running';job.leaseUntil=0;await persist(owner,job);return publicJob(job);}
export async function decideTeamJob(owner:string,b:any){const job=await getJob(owner,b.id);if(job.version!==b.version)throw new Error('결정 전에 최신 업무 상태를 다시 확인하세요.');if(!['approve','hold','revise','cancel'].includes(b.action))throw new Error('지원하지 않는 결정입니다.');if(b.action==='cancel'){if(!['running','error'].includes(job.status))throw new Error('진행 중인 업무만 중단할 수 있습니다.');job.status='cancelled';}
 else{if(!['awaiting_decision','held'].includes(job.status))throw new Error('완료된 보고서에만 결정할 수 있습니다.');if(b.action==='revise'){const feedback=typeof b.feedback==='string'?b.feedback.trim():'';if(feedback.length<5||feedback.length>2000)throw new Error('수정 요청을 5~2,000자로 입력하세요.');if(job.revision>=3)throw new Error('수정은 업무당 3회까지 가능합니다. 새 업무로 이어가세요.');const active=await db().prepare("SELECT id FROM records WHERE owner=? AND kind='ai-job' AND json_extract(data,'$.status')='running' AND id<>?").bind(owner,b.id).first();if(active)throw new Error('다른 진행 중인 업무를 먼저 완료하세요.');job.archives.push({revision:job.revision,steps:job.steps,feedback:job.feedback||'',savedAt:now()});job.feedback=[job.feedback,feedback].filter(Boolean).join('\n');job.revision++;job.steps=AI_TEAM.map(a=>({role:a.id,status:'queued',attempts:0}));job.status='running';}else job.status=b.action==='approve'?'approved':'held';}
 job.decisions.push({action:b.action,note:typeof b.feedback==='string'?b.feedback.slice(0,2000):'',at:now(),revision:job.revision});job.leaseUntil=0;await persist(owner,job);
 if(b.action==='cancel'){const current=job.steps.find((s:any)=>s.status==='running'&&s.responseId);if(current)try{await cancelTeamResponse(owner,job,current.responseId);}catch{/* Cancellation is best effort; no further stage will be started. */}}
 return publicJob(job);}
